{
  "passages": [
    {
      "id": "m53",
      "about_topic": true,
      "says": "rule: do not pass the smaller vehicle until it moves right when making a left turn"
    },
    {
      "id": "c6",
      "about_topic": true,
      "says": "rule: when making a left turn behind these vehicles, do not pull up beside the vehicle to make the turn at the same time"
    },
    {
      "id": "c7",
      "about_topic": true,
      "says": "rule: stay behind the vehicle and make the left turn when the way is clear"
    },
    {
      "id": "m19",
      "about_topic": true,
      "says": "rule: these left-turn lanes are not to be used for passing"
    }
  ],
  "statements": [
    {
      "id": "s1",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"Wait\")",
      "text": "a driver SHOULD NOT pass [?the smaller vehicle] WHEN the driver is making a left turn UNTIL the smaller vehicle moves right",
      "sources": [
        {
          "id": "m53",
          "quote": "Wait for the smaller vehicle to move right before you pass."
        }
      ],
      "flags": [
        {
          "code": "R",
          "span": "the smaller vehicle",
          "note": "The batch does not identify the smaller vehicle or its relationship to the driver."
        }
      ],
      "links": [],
      "note": "The condition making a left turn comes from the heading; before you pass is written as a prohibition with UNTIL."
    },
    {
      "id": "s2",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"do not\")",
      "text": "a driver SHOULD NOT pull up beside [?one of these vehicles] to make the left turn at the same time as the vehicle makes the turn WHEN the driver is making a left turn behind the vehicle",
      "sources": [
        {
          "id": "c6",
          "quote": "If you are making a left turn behind one of these vehicles, do not pull up beside it to make your turn at the same time."
        }
      ],
      "flags": [
        {
          "code": "R",
          "span": "one of these vehicles",
          "note": "The batch does not include the list or description that these vehicles refers to."
        }
      ],
      "links": [],
      "note": "The pronoun it is resolved as the vehicle; the same time is understood as the vehicle making the turn."
    },
    {
      "id": "s3",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"Stay\")",
      "text": "a driver SHOULD stay behind [?one of these vehicles] WHEN the driver is making a left turn behind the vehicle UNTIL the way is clear",
      "sources": [
        {
          "id": "c7",
          "quote": "Stay behind and turn when the way is clear."
        },
        {
          "id": "c6",
          "quote": "If you are making a left turn behind one of these vehicles, do not pull up beside it to make your turn at the same time."
        }
      ],
      "flags": [
        {
          "code": "R",
          "span": "one of these vehicles",
          "note": "The batch does not include the list or description that these vehicles refers to."
        }
      ],
      "links": [],
      "note": "The object of stay behind and the condition behind one of these vehicles are taken from the neighbouring sentence c6."
    },
    {
      "id": "s4",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"turn\")",
      "text": "a driver SHOULD make the left turn WHEN the driver is making a left turn behind [?one of these vehicles] AND the way is clear",
      "sources": [
        {
          "id": "c7",
          "quote": "Stay behind and turn when the way is clear."
        },
        {
          "id": "c6",
          "quote": "If you are making a left turn behind one of these vehicles, do not pull up beside it to make your turn at the same time."
        }
      ],
      "flags": [
        {
          "code": "R",
          "span": "one of these vehicles",
          "note": "The batch does not include the list or description that these vehicles refers to."
        }
      ],
      "links": [],
      "note": "The condition making a left turn behind one of these vehicles is taken from c6; turn is expanded to make the left turn from the heading."
    },
    {
      "id": "s5",
      "type": "RULE",
      "force": "LEGAL",
      "force_from": "text (\"not to be used\")",
      "text": "a driver MUST NOT use [?these left-turn lanes] for passing",
      "sources": [
        {
          "id": "m19",
          "quote": "These left-turn lanes are not to be used for passing."
        }
      ],
      "flags": [
        {
          "code": "R",
          "span": "these left-turn lanes",
          "note": "The batch does not identify which left-turn lanes are meant."
        }
      ],
      "links": [],
      "note": "The passive prohibition is written as a rule for the driver using the lanes."
    }
  ]
}
